sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var ga = new GlideAjax('AssetLoanUtils');
    ga.addParam('sysparm_name', 'ajaxIsAssetAvailable');
    ga.addParam('sysparm_asset_id', newValue);
    ga.getXML(function(response) {
    var available = response.responseXML.documentElement.getAttribute('answer');
    if (available === 'false') {
        g_form.setValue('asset', '');
        g_form.addErrorMessage('The asset you asked for is currently on loan and not available.');
    }
});
}
